# INC-5521: Oversold stock and stuck holds during the September flash sale

Reported by the checkout team after the 2026-09-12 flash sale.

## What we saw

- The `sneaker-limited` drop had 250 units. We confirmed 263 orders, and 13
  customers had to be refunded.
- The stock dashboard showed `reserved` going negative for two SKUs after the
  sale, and it has not recovered.
- Some customers who retried checkout after a timeout had units held twice for
  one order; the second hold only disappeared when the reservation expired.
- One order was rejected because a bundle item was out of stock, but the other
  item in the bundle stayed held until we restarted the worker pool.
- Finance reports `sold` counts that are higher than the number of orders we
  shipped for a few SKUs.

## Context

Every checkout worker calls `InventoryService` concurrently. During the sale
we ran 40 workers. The nightly `expire()` job ran once during the sale.

The unit tests all pass, and none of this reproduces when we click through
checkout by hand.

A service-wide lock (INC-5490) stopped the overselling in staging but cut
checkout throughput by 90% and was rolled back the same day.
'use strict';

class InventoryError extends Error {
  constructor(message, code) {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
  }
}

class ValidationError extends InventoryError {
  constructor(message) {
    super(message, 'VALIDATION');
  }
}

class UnknownSkuError extends InventoryError {
  constructor(sku) {
    super(`unknown sku: ${sku}`, 'UNKNOWN_SKU');
    this.sku = sku;
  }
}

class UnknownOrderError extends InventoryError {
  constructor(orderId) {
    super(`unknown order: ${orderId}`, 'UNKNOWN_ORDER');
    this.orderId = orderId;
  }
}

class InsufficientStockError extends InventoryError {
  constructor(sku, requested, available) {
    super(`insufficient stock for ${sku}: requested ${requested}, available ${available}`, 'INSUFFICIENT_STOCK');
    this.sku = sku;
    this.requested = requested;
    this.available = available;
  }
}

class OrderStateError extends InventoryError {
  constructor(orderId, status, action) {
    super(`cannot ${action} order ${orderId}: it is ${status}`, 'ORDER_STATE');
    this.orderId = orderId;
    this.status = status;
  }
}

module.exports = {
  InventoryError,
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError,
  OrderStateError
};
'use strict';

module.exports = {
  ...require('./inventory'),
  ...require('./errors'),
  ...require('./store')
};
'use strict';

const { Store } = require('./store');
const {
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError,
  OrderStateError
} = require('./errors');

const DEFAULT_TTL_MS = 15 * 60 * 1000;

/**
 * Stock reservations for checkout.
 *
 * Every SKU has three counters: `stock` (units on hand), `reserved` (units
 * held for orders that have not been committed) and `sold`. Available stock
 * is `stock - reserved` and must never go below zero.
 *
 * An order moves reserved -> committed, or reserved -> released. Committing
 * turns its held units into sold units; releasing returns them.
 *
 * The service is called concurrently by every checkout worker. Every change
 * runs under locks on just the order and SKUs it touches, so calls that share
 * neither run in parallel. A call takes at most one order lock, takes it
 * before any SKU lock, and takes SKU locks in sorted order, so calls cannot
 * deadlock. Locks belong to the store: services sharing a store share them.
 */
class InventoryService {
  constructor({ store = new Store(), reservationTtlMs = DEFAULT_TTL_MS, now = () => Date.now() } = {}) {
    this.store = store;
    this.ttl = reservationTtlMs;
    this.now = now;
  }

  /** Add units to a SKU, creating it if needed. Returns the SKU snapshot. */
  async addStock(sku, qty) {
    assertSku(sku);
    assertQty(qty);
    return this.#locked([skuKey(sku)], async () => {
      const item = (await this.store.get(skuKey(sku))) || { stock: 0, reserved: 0, sold: 0 };
      item.stock += qty;
      await this.store.set(skuKey(sku), item);
      return { sku, ...item };
    });
  }

  /** Units that can still be reserved. */
  async available(sku) {
    const item = await this.getItem(sku);
    return item.stock - item.reserved;
  }

  /** The SKU's counters. */
  async snapshot(sku) {
    const item = await this.getItem(sku);
    return { sku, stock: item.stock, reserved: item.reserved, sold: item.sold };
  }

  /**
   * Hold stock for an order: all of its items, or none of them.
   *
   * Idempotent by orderId: checkout retries a timed-out request with the same
   * orderId, and a retry must return the existing reservation rather than
   * hold the stock twice.
   *
   * Rejects with InsufficientStockError when any item cannot be held, and
   * then holds nothing.
   */
  async reserve(orderId, items) {
    assertOrderId(orderId);
    assertItems(items);
    const wanted = items.map(({ sku, qty }) => ({ sku, qty }));
    // The order lock makes a retry wait for the original call, then find its order.
    return this.#locked([orderKey(orderId)], async () => {
      const existing = await this.store.get(orderKey(orderId));
      if (existing) {
        return toReservation(existing);
      }
      return this.#locked(skuKeys(wanted), async () => {
        const counters = await Promise.all(wanted.map(({ sku }) => this.store.get(skuKey(sku))));
        // Check every item before holding any, so a rejected order holds nothing.
        for (const [i, { sku, qty }] of wanted.entries()) {
          if (!counters[i]) {
            throw new UnknownSkuError(sku);
          }
          const free = counters[i].stock - counters[i].reserved;
          if (free < qty) {
            throw new InsufficientStockError(sku, qty, free);
          }
        }
        wanted.forEach(({ qty }, i) => { counters[i].reserved += qty; });
        const order = { orderId, items: wanted, status: 'reserved', createdAt: this.now() };
        await setAll(this.store, [
          ...wanted.map(({ sku }, i) => [skuKey(sku), counters[i]]),
          [orderKey(orderId), order]
        ]);
        return toReservation(order);
      });
    });
  }

  /**
   * Turn a reservation into a sale. Idempotent: committing a committed order
   * returns it unchanged. A released order cannot be committed.
   */
  async commit(orderId) {
    assertOrderId(orderId);
    return this.#withOrder(orderId, order => {
      if (order.status === 'committed') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'commit');
      }
      return this.#settle(order, 'committed', sellHeld);
    });
  }

  /**
   * Cancel a reservation and return its units. Idempotent: releasing a
   * released order returns it unchanged. A committed order cannot be
   * released; its units have been sold.
   */
  async release(orderId) {
    assertOrderId(orderId);
    return this.#withOrder(orderId, order => {
      if (order.status === 'released') {
        return toReservation(order);
      }
      if (order.status !== 'reserved') {
        throw new OrderStateError(orderId, order.status, 'release');
      }
      return this.#settle(order, 'released', returnHeld);
    });
  }

  /**
   * Release every reservation older than the TTL that has not been committed
   * or released. Returns the orderIds it released.
   */
  async expire() {
    const cutoff = this.now() - this.ttl;
    const isStale = order => order.status === 'reserved' && order.createdAt < cutoff;
    const released = [];
    for (const key of await this.store.keys('order:')) {
      // Committed and released are final, so only a stale reservation is worth
      // locking. It is checked again under the lock, since checkout may have
      // committed or released it in the meantime.
      const order = await this.store.get(key);
      if (!order || !isStale(order)) {
        continue;
      }
      const expired = await this.#withOrder(order.orderId, async current => {
        if (!isStale(current)) {
          return false;
        }
        await this.#settle(current, 'released', returnHeld);
        return true;
      });
      if (expired) {
        released.push(order.orderId);
      }
    }
    return released;
  }

  async getItem(sku) {
    assertSku(sku);
    const item = await this.store.get(skuKey(sku));
    if (!item) {
      throw new UnknownSkuError(sku);
    }
    return item;
  }

  async getOrder(orderId) {
    assertOrderId(orderId);
    const order = await this.store.get(orderKey(orderId));
    if (!order) {
      throw new UnknownOrderError(orderId);
    }
    return order;
  }

  #locked(keys, fn) {
    return withLocks(locksFor(this.store), keys, fn);
  }

  // Runs fn with the order, read while holding its lock.
  #withOrder(orderId, fn) {
    return this.#locked([orderKey(orderId)], async () => fn(await this.getOrder(orderId)));
  }

  // Moves a reserved order to `status`, applying `update` to each of its SKUs'
  // counters. The caller holds the order's lock.
  #settle(order, status, update) {
    return this.#locked(skuKeys(order.items), async () => {
      const counters = await Promise.all(order.items.map(({ sku }) => this.getItem(sku)));
      order.items.forEach(({ qty }, i) => update(counters[i], qty));
      order.status = status;
      await setAll(this.store, [
        ...order.items.map(({ sku }, i) => [skuKey(sku), counters[i]]),
        [orderKey(order.orderId), order]
      ]);
      return toReservation(order);
    });
  }
}

function sellHeld(item, qty) {
  item.reserved -= qty;
  item.stock -= qty;
  item.sold += qty;
}

function returnHeld(item, qty) {
  item.reserved -= qty;
}

// Writes every entry, and waits for all of them even if one fails, so that no
// write is still in flight once the caller's locks are released.
async function setAll(store, entries) {
  const results = await Promise.allSettled(entries.map(([key, value]) => store.set(key, value)));
  const failed = results.find(result => result.status === 'rejected');
  if (failed) {
    throw failed.reason;
  }
}

// Lock tables by store: key -> promise that settles when the key's last
// queued holder unlocks it. Keys with nobody holding or waiting are removed.
const lockTables = new WeakMap();

function locksFor(store) {
  let locks = lockTables.get(store);
  if (!locks) {
    locks = new Map();
    lockTables.set(store, locks);
  }
  return locks;
}

// Runs fn while holding every key's lock, taking them in the order given.
async function withLocks(locks, keys, fn) {
  const unlocks = [];
  try {
    for (const key of keys) {
      unlocks.push(await lock(locks, key));
    }
    return await fn();
  } finally {
    unlocks.reverse().forEach(unlock => unlock());
  }
}

// Queues for the key's lock, first come first served. Resolves to the
// function that unlocks it.
async function lock(locks, key) {
  const previous = locks.get(key);
  let unlock;
  const current = new Promise(resolve => { unlock = resolve; });
  locks.set(key, current);
  await previous;
  return () => {
    if (locks.get(key) === current) {
      locks.delete(key);
    }
    unlock();
  };
}

function skuKey(sku) {
  return `sku:${sku}`;
}

function orderKey(orderId) {
  return `order:${orderId}`;
}

// Sorted, so that every call takes SKU locks in the same order.
function skuKeys(items) {
  return items.map(({ sku }) => skuKey(sku)).sort();
}

function toReservation(order) {
  return { orderId: order.orderId, status: order.status, items: order.items.map(({ sku, qty }) => ({ sku, qty })) };
}

function assertSku(sku) {
  if (typeof sku !== 'string' || sku.trim() === '') {
    throw new ValidationError('sku must be a non-empty string');
  }
}

function assertOrderId(orderId) {
  if (typeof orderId !== 'string' || orderId.trim() === '') {
    throw new ValidationError('orderId must be a non-empty string');
  }
}

function assertQty(qty) {
  if (!Number.isInteger(qty) || qty <= 0) {
    throw new ValidationError('qty must be a positive integer');
  }
}

function assertItems(items) {
  if (!Array.isArray(items) || items.length === 0) {
    throw new ValidationError('items must be a non-empty array');
  }
  const seen = new Set();
  for (const entry of items) {
    if (!entry || typeof entry !== 'object') {
      throw new ValidationError('each item must be an object with sku and qty');
    }
    assertSku(entry.sku);
    assertQty(entry.qty);
    if (seen.has(entry.sku)) {
      throw new ValidationError(`duplicate sku in items: ${entry.sku}`);
    }
    seen.add(entry.sku);
  }
}

module.exports = { InventoryService, DEFAULT_TTL_MS };
'use strict';

// In-memory key-value store with the latency profile of the Redis cluster
// used in production: every call yields to the event loop before it reads or
// writes, so concurrent callers interleave the way they do against the real
// store. Values are copied on the way in and out.
class Store {
  constructor() {
    this.data = new Map();
  }

  async get(key) {
    await tick();
    const value = this.data.get(key);
    return value === undefined ? undefined : structuredClone(value);
  }

  async set(key, value) {
    await tick();
    this.data.set(key, structuredClone(value));
  }

  async keys(prefix) {
    await tick();
    return [...this.data.keys()].filter(key => key.startsWith(prefix));
  }
}

function tick() {
  return new Promise(resolve => setImmediate(resolve));
}

module.exports = { Store };
'use strict';

// Reproductions for INC-5521. Checkout workers call the service concurrently,
// so most of these start overlapping calls and check the counters afterwards.

const test = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  UnknownSkuError,
  UnknownOrderError,
  OrderStateError
} = require('../src');

// Enough store round-trips for the gap to land anywhere inside the first call.
const GAPS = [0, 1, 2, 3, 4, 5, 6, 8];

async function service(stock = { widget: 10 }, options = {}) {
  const svc = new InventoryService(options);
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

function ticks(n) {
  let p = Promise.resolve();
  for (let i = 0; i < n; i++) {
    p = p.then(() => new Promise(resolve => setImmediate(resolve)));
  }
  return p;
}

// Starts `first`, lets `gap` event-loop turns pass, then starts `second`.
async function race(first, second, gap) {
  const a = first();
  await ticks(gap);
  const b = second();
  return Promise.allSettled([a, b]);
}

function counters(snapshot) {
  const { stock, reserved, sold } = snapshot;
  return { stock, reserved, sold };
}

function mulberry32(seed) {
  return () => {
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// Same three methods as Store, but each call takes a random number of
// event-loop turns and hands out its own objects instead of copies.
class JitteryStore {
  constructor(seed) {
    this.data = new Map();
    this.random = mulberry32(seed);
  }

  async get(key) {
    await ticks(Math.floor(this.random() * 4));
    return this.data.get(key);
  }

  async set(key, value) {
    await ticks(Math.floor(this.random() * 4));
    this.data.set(key, value);
  }

  async keys(prefix) {
    await ticks(Math.floor(this.random() * 4));
    return [...this.data.keys()].filter(key => key.startsWith(prefix));
  }
}

// A Store whose reads of a key can be held until the test lets them through.
class GatedStore extends Store {
  constructor() {
    super();
    this.gates = new Map();
  }

  close(key) {
    let open;
    this.gates.set(key, new Promise(resolve => { open = resolve; }));
    return () => {
      this.gates.delete(key);
      open();
    };
  }

  async get(key) {
    await this.gates.get(key);
    return super.get(key);
  }
}

// Every SKU's counters must agree with the orders in the store.
async function assertConsistent(store, added) {
  const expected = {};
  for (const [sku, stock] of Object.entries(added)) {
    expected[sku] = { stock, reserved: 0, sold: 0 };
  }
  for (const key of await store.keys('order:')) {
    const order = await store.get(key);
    for (const { sku, qty } of order.items) {
      if (order.status === 'reserved') expected[sku].reserved += qty;
      if (order.status === 'committed') {
        expected[sku].sold += qty;
        expected[sku].stock -= qty;
      }
    }
  }
  for (const [sku, want] of Object.entries(expected)) {
    const item = await store.get(`sku:${sku}`);
    assert.deepEqual(counters(item), want, `counters for ${sku}`);
    assert.ok(item.stock - item.reserved >= 0, `available for ${sku} is negative`);
  }
}

// --- Oversold stock ---------------------------------------------------------

test('263 concurrent orders for 250 units confirm exactly 250', async () => {
  const svc = await service({ 'sneaker-limited': 250 });
  const results = await Promise.allSettled(
    Array.from({ length: 263 }, (_, i) => svc.reserve(`order-${i}`, [{ sku: 'sneaker-limited', qty: 1 }]))
  );
  const rejected = results.filter(r => r.status === 'rejected');
  assert.equal(results.length - rejected.length, 250);
  assert.equal(rejected.length, 13);
  for (const { reason } of rejected) {
    assert.ok(reason instanceof InsufficientStockError, reason);
  }
  assert.deepEqual(counters(await svc.snapshot('sneaker-limited')), { stock: 250, reserved: 250, sold: 0 });

  const confirmed = results.map((r, i) => r.status === 'fulfilled' && `order-${i}`).filter(Boolean);
  await Promise.all(confirmed.map(orderId => svc.commit(orderId)));
  assert.deepEqual(counters(await svc.snapshot('sneaker-limited')), { stock: 0, reserved: 0, sold: 250 });
});

test('restocking while orders reserve and commit loses no update', async () => {
  const svc = await service({ widget: 10 });
  await svc.reserve('o-commit', [{ sku: 'widget', qty: 2 }]);
  await Promise.all([
    svc.commit('o-commit'),
    ...Array.from({ length: 5 }, (_, i) => svc.reserve(`o${i}`, [{ sku: 'widget', qty: 1 }])),
    ...Array.from({ length: 3 }, () => svc.addStock('widget', 4))
  ]);
  assert.deepEqual(counters(await svc.snapshot('widget')), { stock: 20, reserved: 5, sold: 2 });
});

test('concurrent first restocks of a new sku are all counted', async () => {
  const svc = new InventoryService();
  await Promise.all(Array.from({ length: 10 }, () => svc.addStock('fresh', 3)));
  assert.deepEqual(counters(await svc.snapshot('fresh')), { stock: 30, reserved: 0, sold: 0 });
});

// --- Retried checkouts holding stock twice -----------------------------------

test('a retry that overlaps the original reserve holds the stock once', async () => {
  for (const gap of GAPS) {
    const svc = await service();
    const reserve = () => svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
    const [first, retry] = await race(reserve, reserve, gap);
    const reservation = { orderId: 'o1', status: 'reserved', items: [{ sku: 'widget', qty: 2 }] };
    assert.deepEqual(first.value, reservation, `gap ${gap}`);
    assert.deepEqual(retry.value, reservation, `gap ${gap}`);
    assert.equal(await svc.available('widget'), 8, `gap ${gap}`);
    await svc.release('o1');
    assert.equal(await svc.available('widget'), 10, `gap ${gap}`);
  }
});

test('a cancel sent while the timed-out reserve is still running releases its hold', async () => {
  for (const gap of GAPS) {
    const svc = await service();
    const [reserved, released] = await race(
      () => svc.reserve('o1', [{ sku: 'widget', qty: 2 }]),
      () => svc.release('o1'),
      gap
    );
    assert.equal(reserved.status, 'fulfilled', `gap ${gap}`);
    assert.equal(released.value?.status, 'released', `gap ${gap}: ${released.reason}`);
    assert.deepEqual(counters(await svc.snapshot('widget')), { stock: 10, reserved: 0, sold: 0 }, `gap ${gap}`);
  }
});

// --- Bundles left half-held ---------------------------------------------------

test('a bundle with an out-of-stock item holds none of its items', async () => {
  const svc = await service({ shoe: 5, lace: 1 });
  await assert.rejects(
    svc.reserve('o1', [{ sku: 'shoe', qty: 2 }, { sku: 'lace', qty: 2 }]),
    InsufficientStockError
  );
  assert.equal(await svc.available('shoe'), 5);
  assert.equal(await svc.available('lace'), 1);
  await assert.rejects(svc.release('o1'), UnknownOrderError);
});

test('a bundle with an unknown sku holds none of its items', async () => {
  const svc = await service({ shoe: 5 });
  await assert.rejects(svc.reserve('o1', [{ sku: 'shoe', qty: 2 }, { sku: 'nope', qty: 1 }]), UnknownSkuError);
  assert.equal(await svc.available('shoe'), 5);
});

test('bundles competing for the last units in opposite order: one wins, no partial holds, no deadlock', { timeout: 5000 }, async () => {
  for (const gap of GAPS) {
    const svc = await service({ shoe: 1, lace: 1 });
    const [a, b] = await race(
      () => svc.reserve('o1', [{ sku: 'shoe', qty: 1 }, { sku: 'lace', qty: 1 }]),
      () => svc.reserve('o2', [{ sku: 'lace', qty: 1 }, { sku: 'shoe', qty: 1 }]),
      gap
    );
    assert.deepEqual([a.status, b.status].sort(), ['fulfilled', 'rejected'], `gap ${gap}`);
    assert.ok((a.reason || b.reason) instanceof InsufficientStockError, `gap ${gap}`);
    assert.deepEqual(counters(await svc.snapshot('shoe')), { stock: 1, reserved: 1, sold: 0 }, `gap ${gap}`);
    assert.deepEqual(counters(await svc.snapshot('lace')), { stock: 1, reserved: 1, sold: 0 }, `gap ${gap}`);
  }
});

// --- reserved going negative ------------------------------------------------

test('expire leaves committed orders alone', async () => {
  let t = 0;
  const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
  await svc.reserve('o1', [{ sku: 'widget', qty: 2 }]);
  await svc.commit('o1');
  t = 5000;
  assert.deepEqual(await svc.expire(), []);
  assert.deepEqual(counters(await svc.snapshot('widget')), { stock: 8, reserved: 0, sold: 2 });
  assert.equal((await svc.commit('o1')).status, 'committed');
});

test('a committed order cannot be released', async () => {
  const svc = await service();
  await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
  await svc.commit('o1');
  await assert.rejects(svc.release('o1'), OrderStateError);
  assert.deepEqual(counters(await svc.snapshot('widget')), { stock: 7, reserved: 0, sold: 3 });
});

test('overlapping releases of one order return its units once', async () => {
  for (const gap of GAPS) {
    const svc = await service();
    await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
    const results = await race(() => svc.release('o1'), () => svc.release('o1'), gap);
    for (const r of results) assert.equal(r.value?.status, 'released', `gap ${gap}: ${r.reason}`);
    assert.deepEqual(counters(await svc.snapshot('widget')), { stock: 10, reserved: 0, sold: 0 }, `gap ${gap}`);
  }
});

test('expire racing a checkout release returns the units once', async () => {
  for (const gap of GAPS) {
    let t = 0;
    const svc = await service({ widget: 10 }, { now: () => t, reservationTtlMs: 1000 });
    await svc.reserve('o1', [{ sku: 'widget', qty: 4 }]);
    t = 5000;
    for (const [first, second] of [[() => svc.expire(), () => svc.release('o1')], [() => svc.release('o1'), () => svc.expire()]]) {
      const results = await race(first, second, gap);
      for (const r of results) assert.equal(r.status, 'fulfilled', `gap ${gap}: ${r.reason}`);
      assert.deepEqual(counters(await svc.snapshot('widget')), { stock: 10, reserved: 0, sold: 0 }, `gap ${gap}`);
    }
  }
});

// --- sold higher than shipped -------------------------------------------------

test('overlapping commits of one order sell its units once', async () => {
  for (const gap of GAPS) {
    const svc = await service();
    await svc.reserve('o1', [{ sku: 'widget', qty: 3 }]);
    const results = await race(() => svc.commit('o1'), () => svc.commit('o1'), gap);
    for (const r of results) assert.equal(r.value?.status, 'committed', `gap ${gap}: ${r.reason}`);
    assert.deepEqual(counters(await svc.snapshot('widget')), { stock: 7, reserved: 0, sold: 3 }, `gap ${gap}`);
