'use strict';

// Reproductions for INC-5521. Checkout workers call the service concurrently,
// so most of these start overlapping calls and check the counters afterwards.

const test = require('node:test');
const assert = require('node:assert/strict');
const {
  InventoryService,
  Store,
  InsufficientStockError,
  UnknownSkuError,
  UnknownOrderError,
  OrderStateError
} = require('../src');

// Enough store round-trips for the gap to land anywhere inside the first call.
const GAPS = [0, 1, 2, 3, 4, 5, 6, 8];

async function service(stock = { widget: 10 }, options = {}) {
  const svc = new InventoryService(options);
  for (const [sku, qty] of Object.entries(stock)) {
    await svc.addStock(sku, qty);
  }
  return svc;
}

function ticks(n) {
  let p = Promise.resolve();
  for (let i = 0; i < n; i++) {
    p = p.then(() => new Promise(resolve => setImmediate(resolve)));
  }
  return p;
}

// Starts `first`, lets `gap` event-loop turns pass, then starts `second`.
async function race(first, second, gap) {
  const a = first();
  await ticks(gap);
  const b = second();

class InsufficientStockError extends InventoryError {
  constructor(sku, requested, available) {
    super(`insufficient stock for ${sku}: requested ${requested}, available ${available}`, 'INSUFFICIENT_STOCK');
    this.sku = sku;
    this.requested = requested;
    this.available = available;
  }
}

class OrderStateError extends InventoryError {
  constructor(orderId, status, action) {
    super(`cannot ${action} order ${orderId}: it is ${status}`, 'ORDER_STATE');
    this.orderId = orderId;
    this.status = status;
  }
}

module.exports = {
  InventoryError,
  ValidationError,
  UnknownSkuError,
  UnknownOrderError,
  InsufficientStockError,
  OrderStateError
};

